#!/usr/bin/env python3
"""Build a reproducible submission bundle for Subproject 24.

The bundle contains the manuscript plus key readiness, protocol, and replication
artifacts from the current consolidated project state.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import shutil
from datetime import datetime, timezone
from pathlib import Path
from typing import List

import pandas as pd


def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--bundle-name",
        type=str,
        default="subproject24_submission_bundle_v1",
    )
    parser.add_argument(
        "--output-root",
        type=Path,
        default=Path("subproject_24_multireference_latent_truth_model/paper/submission_bundle"),
    )
    return parser.parse_args()


def _sha256(path: Path) -> str:
    h = hashlib.sha256()
    with path.open("rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _copy_file(src: Path, dst_root: Path) -> Path:
    if not src.exists():
        raise FileNotFoundError(f"Missing required artifact: {src}")
    rel = src.as_posix()
    dst = dst_root / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)
    return dst


