    for src in files:
        dst = _copy_file(src=src, dst_root=bundle_dir)
        copied_rows.append(
            {
                "source_path": src.as_posix(),
                "bundle_path": dst.relative_to(bundle_dir).as_posix(),
                "size_bytes": int(dst.stat().st_size),
                "sha256": _sha256(dst),
            }
        )

    manifest = pd.DataFrame(copied_rows).sort_values("bundle_path").reset_index(drop=True)
    manifest.to_csv(bundle_dir / "bundle_manifest.csv", index=False)

    summary = {
        "bundle_name": args.bundle_name,
        "created_utc": datetime.now(timezone.utc).isoformat(),
        "n_files": int(len(copied_rows)),
        "total_size_bytes": int(manifest["size_bytes"].sum()),
        "primary_pdf": "subproject_24_multireference_latent_truth_model/paper/unified_multireference_latent_truth_full_paper.pdf",
        "readiness_profile": "top_tier_readiness_v5 (10/10 pass)",
        "external_protocol_profile": "top_tier_readiness_v8 (phase XVIII-LXIX artifacts included)",
    }
    (bundle_dir / "bundle_summary.json").write_text(json.dumps(summary, indent=2, sort_keys=True), encoding="utf-8")

    # Zip for transport.
    zip_base = bundle_dir.as_posix()
    shutil.make_archive(zip_base, "zip", root_dir=bundle_dir)

    print("Submission bundle created.")
    print(f"Bundle directory: {bundle_dir}")
    print(f"Bundle zip: {bundle_dir}.zip")
    print(f"Files included: {len(copied_rows)}")


